/**
 * The write lock a subscription that is not in good standing puts on a workspace.
 *
 * Pure: it reads a subscription row and a clock, and decides. The service layer
 * loads the row and throws; nothing here touches storage.
 */
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

const LOCK_MESSAGES: Readonly<Record<WorkspaceLockReason, string>> = {
  past_due: "This workspace is read-only until its payment is resolved.",
  trial_ended:
    "This workspace is read-only because its trial has ended. Choose a plan to continue.",
  canceled: "This workspace is read-only because its subscription has been canceled.",
};

/** Raised by every guarded write while the workspace is locked. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(LOCK_MESSAGES[reason]);
    this.name = "WorkspaceLockedError";
  }
}

/**
 * The lock a subscription imposes at `now`, or `null` when writes are allowed.
 *
 * A missing row or an `active` subscription is writable. A trial locks once its
 * period end is reached. A cancellation locks once its cancel date is reached;
 * a canceled subscription with no date counts as canceled now.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return hasReached(subscription.currentPeriodEnd, now) ? "trial_ended" : null;
    case "canceled":
      if (subscription.cancelAt === null) return "canceled";
      return hasReached(subscription.cancelAt, now) ? "canceled" : null;
  }
}

function hasReached(stamp: string, now: Date): boolean {
  return new Date(stamp).getTime() <= now.getTime();
}

