/**
 * The pure lock rule: which subscription states make a workspace read-only, and from when.
 */
import { describe, expect, it } from "vitest";
import { lockReasonFor } from "@/lib/billing-lock";
import type { Subscription } from "@/types/billing";

const PERIOD_END = "2026-06-01T00:00:00.000Z";
const BEFORE = new Date("2026-05-31T23:59:59.000Z");
const AT = new Date("2026-06-01T00:00:00.000Z");
const AFTER = new Date("2026-06-02T00:00:00.000Z");

function subscriptionWith(overrides: Partial<Subscription>): Subscription {
  return {
    id: "sub_1",
    orgId: "org_1",
    plan: "growth",
    interval: "monthly",
    status: "active",
    seats: 1,
    currentPeriodStart: "2026-05-01T00:00:00.000Z",
    currentPeriodEnd: PERIOD_END,
    cancelAt: null,
    createdAt: "2026-05-01T00:00:00.000Z",
    updatedAt: "2026-05-01T00:00:00.000Z",
    ...overrides,
  } as unknown as Subscription;
}

describe("lib/billing-lock lockReasonFor", () => {
  it("leaves a workspace with no subscription row writable", () => {
    expect(lockReasonFor(null, AFTER)).toBeNull();
  });

  it("leaves an active subscription writable, even past its period end", () => {
    expect(lockReasonFor(subscriptionWith({ status: "active" }), AFTER)).toBeNull();
  });

  it("locks a past_due subscription at any time", () => {
    const subscription = subscriptionWith({ status: "past_due" });
    expect(lockReasonFor(subscription, BEFORE)).toBe("past_due");
    expect(lockReasonFor(subscription, AFTER)).toBe("past_due");
  });

  it("locks a trial only once its period end is reached", () => {
    const trialing = subscriptionWith({ status: "trialing" });
    expect(lockReasonFor(trialing, BEFORE)).toBeNull();
    expect(lockReasonFor(trialing, AT)).toBe("trial_ended");
    expect(lockReasonFor(trialing, AFTER)).toBe("trial_ended");
  });

  it("locks a canceled subscription with no cancellation date now", () => {
    expect(lockReasonFor(subscriptionWith({ status: "canceled" }), BEFORE)).toBe("canceled");
  });

  it("keeps a canceled subscription writable until its cancellation date", () => {
    const scheduled = subscriptionWith({ status: "canceled", cancelAt: PERIOD_END });
    expect(lockReasonFor(scheduled, BEFORE)).toBeNull();
    expect(lockReasonFor(scheduled, AT)).toBe("canceled");
    expect(lockReasonFor(scheduled, AFTER)).toBe("canceled");
  });
});

