/**
 * A locked workspace is read-only: guarded writes are refused, reads and billing keep working,
 * and a successful plan change unlocks it.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { WorkspaceLockedError } from "@/lib/billing-lock";
import { toAppError } from "@/lib/errors";
import { toIsoTimestamp } from "@/types/common";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as billingService from "@/server/services/billing-service";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("services/workspace lock", () => {
  it("refuses a guarded write while the subscription is canceled, and reports it as plan_limit_exceeded", async () => {
    const tenant: Tenant = await createTenant("locked-write", "growth");
    await subscriptionRepo.cancelSubscription(tenant.org.id, toIsoTimestamp(new Date()));

    const attempt = issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Blocked while locked" }),
    );

    await expect(attempt).rejects.toBeInstanceOf(WorkspaceLockedError);
    await expect(attempt).rejects.toMatchObject({ reason: "canceled", orgId: tenant.org.id });
    expect(toAppError(await attempt.catch((error: unknown) => error))).toMatchObject({
      code: "plan_limit_exceeded",
      meta: { reason: "canceled" },
    });
  });

  it("keeps the billing summary readable and reports the lock", async () => {
    const tenant = await createTenant("locked-summary", "growth");
    await subscriptionRepo.cancelSubscription(tenant.org.id, toIsoTimestamp(new Date()));

    const summary = await billingService.getBillingSummary(tenant.actors.owner, tenant.org.id);

    expect(summary.lockReason).toBe("canceled");
  });

  it("unlocks the workspace once a plan change succeeds", async () => {
    const tenant = await createTenant("locked-unlock", "growth");
    await subscriptionRepo.cancelSubscription(tenant.org.id, toIsoTimestamp(new Date()));

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "enterprise",
      interval: "monthly",
    });

    await expect(billingService.assertWorkspaceWritable(tenant.org.id)).resolves.toBeUndefined();
  });
});

